"use client";

import { useState } from "react";
import {
  type CompanderState,
  companderDevice,
} from "@/components/audio-ui/devices/compander/device";
import { createCompanderEngine } from "@/components/audio-ui/devices/compander/engine";
import { CompanderPanel } from "@/components/audio-ui/devices/compander/panel";
import { useDeviceLoop } from "@/hooks/use-device-loop";
import { useMasterBus } from "@/hooks/use-master-bus";

const MASTER_VOLUME = 0.7;

/**
 * A compander you can plug in: its state, a panel that draws its curve with a
 * handle on each point and an engine that plays it, each its own file and
 * none knowing the others. Play the loop and drag the points: under the
 * straight line of a clean sound they turn it down, over it up.
 */
export function BlockCompander() {
  const [state, setState] = useState<CompanderState>(() =>
    companderDevice.defaults()
  );
  const master = useMasterBus(MASTER_VOLUME);
  useDeviceLoop({
    create: createCompanderEngine,
    destination: master,
    state,
  });
  return (
    <div className="rounded-4xl h-full w-full min-w-0">
      <CompanderPanel onValueChange={setState} value={state} />
    </div>
  );
}
